#!/usr/bin/env python3
"""Layered network health probe (read-only).

Three independent metrics, all measured through the *system default route*
(never pinned to a device):

  base      - default gateway reachable, DNS resolves, generic HTTPS reachable
  remote    - ToDesk / SunLogin cloud endpoints reachable (TCP+TLS) and whether
              a remote-control TCP session currently exists
  download  - a 1 MiB ranged download from hf-mirror really completes

Output: JSON on stdout (with --json), exit 0 always (callers decide).

--mock FILE : read simulated values instead of touching the network (tests).
"""
import argparse
import json
import os
import socket
import ssl
import subprocess
import sys
import time
import urllib.request

REMOTE_TARGETS = [
    ("rc10-linux.oray.com", 443),      # SunLogin relay
    ("47.96.66.73", 443),              # SunLogin relay IP
    ("175.27.192.139", 443),           # ToDesk center IP seen working
    ("140.143.177.173", 443),          # ToDesk center IP seen failing
]
DL_URL = ("https://hf-mirror.com/datasets/VideoUFO/VideoUFO/resolve/main/VideoUFO.csv")
DL_BYTES = 1048576


def run(cmd, timeout=8):
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return p.returncode, p.stdout.strip(), p.stderr.strip()
    except Exception as e:
        return 1, "", str(e)


def default_route():
    """(dev, gateway, metric) of the IPv4 default route with lowest metric."""
    rc, out, _ = run(["ip", "-4", "route", "show", "default"])
    best = ("", "", None)
    for line in out.splitlines():
        parts = line.split()
        if "via" not in parts or "dev" not in parts:
            continue
        gw = parts[parts.index("via") + 1]
        dev = parts[parts.index("dev") + 1]
        metric = None
        if "metric" in parts:
            try:
                metric = int(parts[parts.index("metric") + 1])
            except ValueError:
                pass
        if best[2] is None or (metric is not None and metric < best[2]):
            best = (dev, gw, metric)
    return best


def ping(host, timeout=2):
    if not host:
        return False
    rc, _, _ = run(["ping", "-c", "1", "-W", str(timeout), host], timeout=timeout + 2)
    return rc == 0


def dns_ok(host="hf-mirror.com"):
    try:
        socket.getaddrinfo(host, 443, socket.AF_INET)
        return True
    except Exception:
        return False


def https_ok(host="www.baidu.com", timeout=5):
    """HTTPS HEAD through the default route (no device pinning)."""
    try:
        req = urllib.request.Request("https://" + host, method="HEAD")
        ctx = ssl.create_default_context()
        with urllib.request.urlopen(req, timeout=timeout, context=ctx) as r:
            return r.status < 500
    except Exception:
        return False


def tls_probe(host, port, timeout=4):
    """TCP connect + TLS handshake. Returns (tcp_ok, tls_ok, ms)."""
    t0 = time.time()
    tcp_ok = tls_ok = False
    try:
        s = socket.create_connection((host, port), timeout=timeout)
        tcp_ok = True
        ctx = ssl.create_default_context()
        try:
            ss = ctx.wrap_socket(s, server_hostname=host if not host[0].isdigit() else None)
            tls_ok = True
            ss.close()
        except Exception:
            s.close()
    except Exception:
        pass
    return tcp_ok, tls_ok, int((time.time() - t0) * 1000)


def remote_sessions():
    rc, out, _ = run(["ss", "-tnp"], timeout=5)
    if rc != 0:
        return 0
    n = 0
    for line in out.splitlines():
        if ("sunlogin" in line or "ToDesk" in line) and "ESTAB" in line:
            n += 1
    return n


def download_probe():
    t0 = time.time()
    ok = False
    nbytes = 0
    try:
        req = urllib.request.Request(DL_URL, headers={"Range": "bytes=0-%d" % (DL_BYTES - 1)})
        with urllib.request.urlopen(req, timeout=10) as r:
            data = r.read(DL_BYTES)
        nbytes = len(data)
        ok = nbytes == DL_BYTES and data[:8] == b"ID,Topic"
    except Exception:
        pass
    return ok, nbytes, int((time.time() - t0) * 1000)


def probe():
    dev, gw, metric = default_route()
    base_gw = ping(gw)
    base_dns = dns_ok()
    base_https = https_ok()
    remote = {}
    for host, port in REMOTE_TARGETS:
        tcp, tls, ms = tls_probe(host, port)
        remote[host] = {"tcp": tcp, "tls": tls, "ms": ms}
    remote_ok = any(v["tls"] for v in remote.values())
    sess = remote_sessions()
    dl_ok, dl_bytes, dl_ms = download_probe()
    return {
        "ts": time.strftime("%Y-%m-%d %H:%M:%S%z"),
        "default": {"dev": dev, "gw": gw, "metric": metric},
        "base": {"gw": base_gw, "dns": base_dns, "https": base_https,
                 "ok": bool(base_gw and base_dns and base_https)},
        "remote": {"targets": remote, "cloud_ok": remote_ok,
                   "sessions": sess, "ok": bool(remote_ok or sess > 0)},
        "download": {"range_ok": dl_ok, "bytes": dl_bytes, "ms": dl_ms},
    }


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--mock", default="")
    a = ap.parse_args()
    if a.mock:
        data = json.load(open(a.mock))
    else:
        data = probe()
    print(json.dumps(data, indent=1, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())

