BACKOFF = [300, 600, 1200, 2400]   # after consecutive failures
MAX_PER_HOUR = 3
MAX_PER_DAY = 6
PROTECT_AFTER = 3                  # consecutive failed switches -> PROTECTED


def load_state(path):
    if os.path.exists(path):
        try:
            return json.load(open(path))
        except Exception:
            pass
    return {"switch_times": [], "failures": 0, "mode": "NORMAL",
            "last_switch": 0, "protect_until": 0, "last_reason": ""}


def save_state(path, st):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp"
    json.dump(st, open(tmp, "w"), indent=1, ensure_ascii=False)
    os.replace(tmp, path)


def count_recent(times, now, window):
    return sum(1 for t in times if now - t < window)


def wifi_available(ssid, mock_list=None):
    """Fresh active scan - the scan cache is not trusted."""
    if mock_list is not None:
        return ssid in mock_list
    try:
        p = subprocess.run(["nmcli", "-t", "-f", "SSID", "dev", "wifi", "list",
                            "--rescan", "yes"], capture_output=True, text=True, timeout=25)
        return ssid in {l.strip() for l in p.stdout.splitlines() if l.strip()}
    except Exception:
        return False


def decide(health, st, now, available):
    """Pure policy. Returns dict(action, reason, switches_performed)."""
    d = health.get("default", {})
    dev = d.get("dev", "")
    base_ok = bool(health.get("base", {}).get("ok"))
    remote_ok = bool(health.get("remote", {}).get("ok"))
    sessions = int(health.get("remote", {}).get("sessions", 0))
    dl_ok = bool(health.get("download", {}).get("range_ok"))

