        return {"action": "none", "reason": "RATE_LIMIT_HOURLY"}
    if count_recent(st.get("switch_times", []), now, 86400) >= MAX_PER_DAY:
        return {"action": "none", "reason": "RATE_LIMIT_DAILY"}
    if st.get("failures", 0) >= PROTECT_AFTER:
        return {"action": "none", "reason": "FAILURES_EXCEEDED"}

    if available is not None and PREFERRED not in available:
        return {"action": "none", "reason": "PREFERRED_NOT_VISIBLE"}

    return {"action": "switch", "reason": "BASE_DOWN_REMOTE_DOWN", "target": PREFERRED}


