    st = load_state(a.state)
    now = int(time.time())
    available = a.available.split(",") if a.available is not None else None

    decision = decide(health, st, now, available)
    decision["ts"] = time.strftime("%Y-%m-%d %H:%M:%S")
    decision["dry_run"] = not a.apply

    if a.apply and decision["action"] == "switch":
        ok, msg = apply_switch(decision["target"])
        decision["applied"] = ok
        decision["message"] = msg
        st.setdefault("switch_times", []).append(now)
        st["last_switch"] = now
        if ok:
            st["failures"] = 0
        else:
            st["failures"] = st.get("failures", 0) + 1
            if st["failures"] >= PROTECT_AFTER:
                st["mode"] = "PROTECTED"
        save_state(a.state, st)

    st["last_reason"] = decision["reason"]
    save_state(a.state, st)
    os.makedirs(os.path.dirname(DECISION_LOG), exist_ok=True)
    with open(DECISION_LOG, "a") as f:
        f.write(json.dumps(decision, ensure_ascii=False) + "\n")
    print(json.dumps(decision, indent=1, ensure_ascii=False))


if __name__ == "__main__":
    main()

