import json
import os
import re
import socket
import ssl
import subprocess
import sys
import time
import urllib.request

WIFI_DEV = "wlp0s20f3"
REMOTE_TARGETS = [("rc10-linux.oray.com", 443), ("47.96.66.73", 443),
                  ("175.27.192.139", 443), ("140.143.177.173", 443)]
DL_URL = "https://hf-mirror.com/datasets/VideoUFO/VideoUFO/resolve/main/VideoUFO.csv"
SUNLOGIN_LOG = "/var/log/sunlogin/sunlogin_service.log"
TODESK_LOG = "/var/log/todesk/servicenwlrbbmq_%s.log"


def run(cmd, timeout=8):
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return p.returncode, p.stdout.strip(), p.stderr.strip()
    except Exception as e:
        return 1, "", str(e)


def wifi_info():
    rc, out, _ = run(["iw", "dev", WIFI_DEV, "link"])
    ssid = bssid = ""
    signal = None
    associated = "Not connected" not in out and "Connected to" in out
    m = re.search(r"SSID:\s*(.+)", out)
    if m:
        ssid = m.group(1).strip()
    m = re.search(r"Connected to ([0-9a-f:]+)", out)
    if m:
        bssid = m.group(1)
    m = re.search(r"signal:\s*(-?\d+)\s*dBm", out)
    if m:
        signal = int(m.group(1))
    rc, out2, _ = run(["nmcli", "-t", "-f", "GENERAL.STATE,GENERAL.CONNECTION",
                       "device", "show", WIFI_DEV])
    state = con = ""
    for line in out2.splitlines():
        if line.startswith("GENERAL.STATE:"):
            state = line.split(":", 1)[1]
        elif line.startswith("GENERAL.CONNECTION:"):
            con = line.split(":", 1)[1]
    return {"dev": WIFI_DEV, "associated": associated, "ssid": ssid, "bssid": bssid,
            "signal": signal, "nm_state": state, "connection": con}


def route_info():
    rc, out, _ = run(["ip", "-4", "route", "show", "default"])
    dev = gw = ""
    metric = None
    for line in out.splitlines():
        parts = line.split()
        if "via" in parts and "dev" in parts:
            gw = parts[parts.index("via") + 1]
            dev = parts[parts.index("dev") + 1]
            if "metric" in parts:
                try:
                    metric = int(parts[parts.index("metric") + 1])
                except ValueError:
                    pass
            break
    routes = {}
    for host, _ in REMOTE_TARGETS:
        rc2, o2, _ = run(["ip", "route", "get", host], timeout=5)
        routes[host] = o2.split()[0:6]
    return {"dev": dev, "gw": gw, "metric": metric,
            "hijack": bool(dev and dev != WIFI_DEV),
            "to_remote": routes}


def ping(host, timeout=2):
    if not host:
        return False
    rc, _, _ = run(["ping", "-c", "1", "-W", str(timeout), host], timeout=timeout + 2)
    return rc == 0


def dns_ok(host="hf-mirror.com"):
    try:
        socket.getaddrinfo(host, 443, socket.AF_INET)
        return True
    except Exception:
        return False


def https_ok(host="www.baidu.com", timeout=5):
    try:
        req = urllib.request.Request("https://" + host, method="HEAD")
        with urllib.request.urlopen(req, timeout=timeout,
                                    context=ssl.create_default_context()) as r:
            return r.status < 500
    except Exception:
        return False


def tls_probe(host, port, timeout=4):
    t0 = time.time()
    tcp_ok = tls_ok = False
    try:
        s = socket.create_connection((host, port), timeout=timeout)
        tcp_ok = True
        try:
            ctx = ssl.create_default_context()
            ss = ctx.wrap_socket(s, server_hostname=host if not host[0].isdigit() else None)
            tls_ok = True
            ss.close()
        except Exception:
            s.close()
    except Exception:
        pass
    return tcp_ok, tls_ok, int((time.time() - t0) * 1000)


def service_active(name):
    rc, out, _ = run(["systemctl", "is-active", name], timeout=5)
    return out.strip() == "active"


def app_online():
    """Best-effort application-level online state from vendor logs."""
    sl_online = None
    sl_ts = None
    try:
        rc, out, _ = run(["tail", "-n", "400", SUNLOGIN_LOG], timeout=5)
        for line in out.splitlines():
            if "change status to online" in line:
                m = re.search(r"(20\d\d-\d\d-\d\d \d\d:\d\d:\d\d)", line)
                sl_online, sl_ts = True, m.group(1) if m else None
            elif "change status to offline" in line:
                m = re.search(r"(20\d\d-\d\d-\d\d \d\d:\d\d:\d\d)", line)
                sl_online, sl_ts = False, m.group(1) if m else None
    except Exception:
        pass
    td_ok = None
    try:
        path = TODESK_LOG % time.strftime("%Y_%m_%d")
        rc, out, _ = run(["tail", "-n", "400", path], timeout=5)
        td_ok = "AuthOk" in out or "auth ok" in out.lower()
    except Exception:
        pass
    return {"sunlogin_online": sl_online, "sunlogin_ts": sl_ts, "todesk_auth_ok": td_ok}


def remote_sessions():
    rc, out, _ = run(["ss", "-tnp"], timeout=5)
    n = 0
    if rc == 0:
        for line in out.splitlines():
            if ("sunlogin" in line or "ToDesk" in line) and "ESTAB" in line:
                n += 1
    return n


def download_probe():
    t0 = time.time()
    try:
        req = urllib.request.Request(DL_URL, headers={"Range": "bytes=0-262143"})
        with urllib.request.urlopen(req, timeout=8) as r:
            data = r.read(262144)
        ok = len(data) == 262144 and data[:8] == b"ID,Topic"
        return {"range_ok": ok, "bytes": len(data), "ms": int((time.time() - t0) * 1000)}
    except Exception:
        return {"range_ok": False, "bytes": 0, "ms": int((time.time() - t0) * 1000)}


def collect(skip_download=False):
    w = wifi_info()
    r = route_info()
    base = {"gw": ping(r["gw"]), "dns": dns_ok(), "https": https_ok()}
    base["ok"] = bool(base["gw"] and base["dns"] and base["https"])
    targets = {}
    for host, port in REMOTE_TARGETS:
        tcp, tls, ms = tls_probe(host, port)
        targets[host] = {"tcp": tcp, "tls": tls, "ms": ms}
    cloud_ok = any(v["tls"] for v in targets.values())
    services = {"todeskd": service_active("todeskd.service"),
                "sunlogin": service_active("runsunloginclient.service")}
    return {
        "ts": time.strftime("%Y-%m-%d %H:%M:%S%z"),
        "wifi": w, "route": r, "base": base,
        "remote": {"targets": targets, "cloud_ok": cloud_ok,
                   "services": services, "app": app_online(),
                   "sessions": remote_sessions()},
        "download": ({"range_ok": None} if skip_download else download_probe()),
    }


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--mock", default="")
    ap.add_argument("--skip-download", action="store_true")
    a = ap.parse_args()
    data = json.load(open(a.mock)) if a.mock else collect(a.skip_download)
    print(json.dumps(data, indent=1, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())

