#!/usr/bin/env python3
"""Watchdog V3 — bidirectional Wi-Fi failover with state machine and rollback.

Design rules
------------
* Only a *sustained remote-control outage* may trigger a Wi-Fi switch.
* Download-only failures, remote-service failures and single cloud-endpoint
  failures never switch.
* A default route owned by a wired interface is reported as ROUTE_HIJACK and
  never "fixed" by switching Wi-Fi.
* Switching requires: confirmed failure (>=N checks and >=T seconds), target
  profile present, fresh scan visibility, target not in backoff, rate limits,
  and a rollback transaction armed *before* the switch.
* Every switch is verified through the new default route (cloud TLS, not just
  ping); failure rolls back exactly once and enters backoff/protection.
* State is persisted; PROTECTED expires (not permanent), so unattended recovery
  is still possible later while preventing flapping.

CLI
---
  watchdog_v3.py --health h.json --state s.json [--scan "Xiaomi_311,iKuai5G-68ab"]
                 [--apply]   # --apply additionally needs V3_ALLOW_SWITCH=1
Without --apply the command is a dry run: it prints the decision and touches
nothing (state is not advanced).
"""
import argparse
import json
import os
import sys
import time
import uuid

NETS = ["Xiaomi_311", "iKuai5G-68ab"]
WIFI_DEV = "wlp0s20f3"

FAIL_CHECKS = 2          # consecutive unhealthy checks
FAIL_SECONDS = 60        # and sustained for >= 60 s
MIN_INTERVAL = 600       # 10 min between switches
BACKOFF = [300, 600, 1200, 1800]   # 5/10/20/30 min after failed switches
MAX_HOUR = 3
MAX_DAY = 6
FAIL_TO_PROTECT = 3      # consecutive failed switch attempts
VERIFY_TIMEOUT = 45      # seconds allowed for post-switch verification
OBSERVE = 120            # observation window after a switch / NM roam
PROTECT_SECONDS = 3600

STATES = ["HEALTHY", "DEGRADED", "FAILURE_CONFIRMED", "SWITCH_PREPARED",
          "SWITCHING", "VERIFYING", "ROLLBACK", "COOLDOWN", "PROTECTED"]


def default_state():
    return {
        "schema": 3, "state": "HEALTHY", "status": "",
        "consecutive_failures": 0, "first_failure_ts": 0,
        "switch_times": [], "failures_since_success": 0,
        "last_switch_ts": 0, "cooldown_until": 0, "protect_until": 0,
        "target_backoff": {n: {"until": 0, "fails": 0} for n in NETS},
        "current_con": "", "last_connection": "", "obs_until": 0,
        "txn": None, "history": [],
    }


def load_state(path):
    if path and os.path.exists(path):
        try:
            st = json.load(open(path))
            base = default_state()
            base.update(st)
            return base
        except Exception:
            pass
    return default_state()


def save_state(path, st):
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        json.dump(st, f, indent=1, ensure_ascii=False)
    os.replace(tmp, path)


def recent(times, now, window):
    return sum(1 for t in times if now - t < window)


def derive(health):
    """Turn raw health into the signals the policy uses."""
    wifi = health.get("wifi", {}) or {}
    route = health.get("route", {}) or {}
    base = health.get("base", {}) or {}
    remote = health.get("remote", {}) or {}
    services = remote.get("services", {}) or {}
    app = remote.get("app", {}) or {}
    svc_ok = bool(services.get("todeskd", True)) and bool(services.get("sunlogin", True))
    cloud_ok = bool(remote.get("cloud_ok"))
    app_online = app.get("sunlogin_online")
    todesk_ok = app.get("todesk_auth_ok")
    sessions = int(remote.get("sessions", 0) or 0)
    app_healthy = bool(app_online) or bool(todesk_ok) or sessions > 0
    remote_healthy = svc_ok and (cloud_ok or app_healthy)
    return {
        "ssid": wifi.get("ssid", ""), "associated": bool(wifi.get("associated")),
        "connection": wifi.get("connection", ""), "nm_state": wifi.get("nm_state", ""),
        "route_dev": route.get("dev", ""), "hijack": bool(route.get("hijack")),
        "base_ok": bool(base.get("ok")), "cloud_ok": cloud_ok,
        "svc_ok": svc_ok, "app_online": app_online, "sessions": sessions,
        "remote_healthy": remote_healthy, "dl_ok": health.get("download", {}).get("range_ok"),
        "app_healthy": app_healthy,
    }


class FakeExecutor:
    """Test/simulation executor. outcome: dict with switch/rollback booleans."""
    def __init__(self, outcome=None, targets=None, prepare=True):
        self.outcome = outcome or {"switch": True, "rollback": True}
        self.targets = targets or list(NETS)
        self.prepare_ok = prepare
        self.calls = []

    def target_exists(self, name):
        return name in self.targets

    def prepare(self, target, prev, txn):
        self.calls.append(("prepare", target, prev, txn, self.prepare_ok))
        return self.prepare_ok

    def switch(self, target):
        self.calls.append(("switch", target, self.outcome.get("switch", True)))
        return self.outcome.get("switch", True)

    def rollback(self, prev):
        self.calls.append(("rollback", prev, self.outcome.get("rollback", True)))
        return self.outcome.get("rollback", True)


class Engine:
    def __init__(self, state_path, executor, scan=None, allow_switch=False):
        self.path = state_path
        self.ex = executor
        self.scan = scan            # list of visible SSIDs (fresh scan) or None
        self.allow = allow_switch
        self.st = load_state(state_path)

    # -- helpers ---------------------------------------------------------
    def _record(self, now, event, **kw):
        self.st["history"].append({"ts": now, "event": event, **kw})
        self.st["history"] = self.st["history"][-100:]

    def _set(self, now, state, status=""):
        if state != self.st["state"] or status != self.st["status"]:
            self._record(now, "STATE", state=state, status=status)
        self.st["state"] = state
        self.st["status"] = status

    def _target(self, health):
        cur = self.st.get("current_con") or health.get("wifi", {}).get("connection", "")
        for n in NETS:
            if n != cur:
                return n
        return None

    def _limits_ok(self, now):
        if now - self.st.get("last_switch_ts", 0) < MIN_INTERVAL:
            return False, "COOLDOWN"
        if recent(self.st.get("switch_times", []), now, 3600) >= MAX_HOUR:
            return False, "RATE_LIMIT_HOURLY"
        if recent(self.st.get("switch_times", []), now, 86400) >= MAX_DAY:
            return False, "RATE_LIMIT_DAILY"
        if self.st.get("failures_since_success", 0) >= FAIL_TO_PROTECT:
            return False, "FAILURES_EXCEEDED"
        if now < self.st.get("obs_until", 0):
            return False, "OBSERVING"
        return True, ""

    def _target_ok(self, target, now):
        if not target or not self.ex.target_exists(target):
            return False, "TARGET_PROFILE_MISSING"
        tb = self.st["target_backoff"].get(target, {})
        if now < tb.get("until", 0):
            return False, "TARGET_BACKOFF"
        if self.scan is not None and target not in self.scan:
            return False, "TARGET_NOT_VISIBLE"
        if self.scan is None:
            return False, "SCAN_UNAVAILABLE"   # never switch on a stale/absent scan
        return True, ""

    # -- main step -------------------------------------------------------
    def step(self, health, now):
        d = derive(health)
        st = self.st
        cur = d["connection"] or st.get("current_con", "")
        if cur:
            st["current_con"] = cur

        # NM roamed by itself: observe, never fight it.
        if st.get("last_connection") and cur and cur != st["last_connection"]:
            st["obs_until"] = now + OBSERVE
            st["cooldown_until"] = max(st.get("cooldown_until", 0), now + OBSERVE)
            self._record(now, "NM_ROAM", frm=st["last_connection"], to=cur)
        if cur:
            st["last_connection"] = cur

        # 1. route hijack: not a Wi-Fi problem
        if d["hijack"]:
            self._set(now, "DEGRADED", "ROUTE_HIJACK(%s)" % d["route_dev"])
            return self._result("none", "ROUTE_HIJACK")

        # 2. remote services down: never blamed on Wi-Fi
        if not d["svc_ok"]:
            self._set(now, "DEGRADED", "REMOTE_SERVICE_DEGRADED")
            return self._result("none", "REMOTE_SERVICE_DEGRADED")

        # 3. remote healthy -> stay put (download failures are not a reason to switch)
        if d["remote_healthy"]:
            st["consecutive_failures"] = 0
            st["first_failure_ts"] = 0
            if st["state"] == "PROTECTED" and now >= st.get("protect_until", 0):
                st["protect_until"] = 0
                st["failures_since_success"] = 0
            if st["state"] in ("SWITCHING", "VERIFYING", "SWITCH_PREPARED", "ROLLBACK"):
                return self._finish_switch(now, d, healthy=True)
            if d["dl_ok"] is False:
                self._set(now, "DEGRADED", "DOWNLOAD_DEGRADED")
            else:
                self._set(now, "HEALTHY", "")
            return self._result("none", st["status"] or "HEALTHY")

        # 4. remote unhealthy: track the failure
        if st["consecutive_failures"] == 0:
            st["first_failure_ts"] = now
        st["consecutive_failures"] += 1
        sustained = (st["consecutive_failures"] >= FAIL_CHECKS and
                     now - st["first_failure_ts"] >= FAIL_SECONDS)

        if not sustained:
            reason = ("REMOTE_AUTH_FAILURE" if d["cloud_ok"] else
                      ("NETWORK_UNREACHABLE" if not d["base_ok"] else "REMOTE_CLOUD_UNREACHABLE"))
            self._set(now, "DEGRADED", reason)
            return self._result("none", reason)

        # A healthy generic network + working cloud but failed app auth is not a
        # network fault; do not switch for it.
        if d["base_ok"] and d["cloud_ok"] and not d["app_healthy"]:
            self._set(now, "DEGRADED", "REMOTE_AUTH_FAILURE")
            return self._result("none", "REMOTE_AUTH_FAILURE")

        # crash recovery: a switch was in flight when the process died
        if st["state"] in ("SWITCHING", "VERIFYING", "SWITCH_PREPARED"):
            return self._finish_switch(now, d, healthy=False)

        self._set(now, "FAILURE_CONFIRMED", "REMOTE_UNREACHABLE")

        ok, why = self._limits_ok(now)
        if not ok:
            self._set(now, "PROTECTED" if why == "FAILURES_EXCEEDED" else "COOLDOWN",
                      why)
            if why == "FAILURES_EXCEEDED":
                st["protect_until"] = now + PROTECT_SECONDS
            return self._result("none", why)

        target = self._target(health)
        tok, twhy = self._target_ok(target, now)
        if not tok:
            self._set(now, "FAILURE_CONFIRMED", twhy)
            return self._result("none", twhy)

        # prepare transaction (rollback armed before the switch)
        txn = "txn-%d-%s" % (now, uuid.uuid4().hex[:6])
        if not self.ex.prepare(target, cur, txn):
            self._set(now, "FAILURE_CONFIRMED", "ROLLBACK_NOT_ARMED")
            return self._result("none", "ROLLBACK_NOT_ARMED")
        st["txn"] = {"id": txn, "from": cur, "to": target, "prepared_ts": now,
                     "verify_deadline": now + VERIFY_TIMEOUT, "phase": "prepared"}
        self._set(now, "SWITCH_PREPARED", "TO_%s" % target)
        switched = self.ex.switch(target)
        st["txn"]["phase"] = "switching"
        self._record(now, "SWITCH", target=target, ok=switched)
        if not switched:
            return self._finish_switch(now, d, healthy=False)
        self._set(now, "SWITCHING", "TO_%s" % target)
        return self._result("switch", "SWITCHING", target=target)

    def _finish_switch(self, now, d, healthy):
        st = self.st
        txn = st.get("txn") or {}
        if healthy:
            st["switch_times"].append(now)
            st["last_switch_ts"] = now
            st["failures_since_success"] = 0
            st["obs_until"] = now + OBSERVE
            st["txn"] = None
            self._record(now, "SWITCH_VERIFIED", to=txn.get("to"))
            self._set(now, "COOLDOWN", "OBSERVING_AFTER_SWITCH")
            return self._result("verified", "SWITCH_OK", target=txn.get("to"))

        # rollback exactly once
        st["txn"] = txn or None
        self._set(now, "ROLLBACK", "VERIFY_FAILED")
        rb_ok = self.ex.rollback(txn.get("from", "")) if txn.get("from") else False
        self._record(now, "ROLLBACK", ok=rb_ok, to=txn.get("from"))
        st["failures_since_success"] = st.get("failures_since_success", 0) + 1
        tgt = txn.get("to")
        if tgt:
            tb = st["target_backoff"].setdefault(tgt, {"until": 0, "fails": 0})
            tb["fails"] = tb.get("fails", 0) + 1
            idx = min(tb["fails"] - 1, len(BACKOFF) - 1)
            tb["until"] = now + BACKOFF[idx]
        st["txn"] = None
        if not rb_ok or st["failures_since_success"] >= FAIL_TO_PROTECT:
            st["protect_until"] = now + PROTECT_SECONDS
            self._set(now, "PROTECTED", "ROLLBACK_FAILED" if not rb_ok else "FAILURES_EXCEEDED")
            return self._result("rollback_failed" if not rb_ok else "protected",
                                "PROTECTED")
        st["obs_until"] = now + OBSERVE
        self._set(now, "COOLDOWN", "ROLLED_BACK")
        return self._result("rollback", "ROLLBACK_OK", target=tgt)

    def _result(self, action, reason, **kw):
        return {"state": self.st["state"], "status": self.st["status"],
                "action": action, "reason": reason, **kw}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--health", required=True)
    ap.add_argument("--state", default="/home/bn/net_watchdog/staging/state/v3_state.json")
    ap.add_argument("--scan", default="")
    ap.add_argument("--apply", action="store_true")
    a = ap.parse_args()
    health = json.load(open(a.health))
    scan = a.scan.split(",") if a.scan else None
    apply = a.apply and os.environ.get("V3_ALLOW_SWITCH") == "1"
    ex = FakeExecutor(outcome={"switch": False, "rollback": False}) if not apply else None
    if ex is None:
        sys.exit("real executor not implemented in staging; refusing")
    eng = Engine(a.state, ex, scan=scan, allow_switch=apply)
    res = eng.step(health, int(time.time()))
    if apply:
        save_state(a.state, eng.st)
    print(json.dumps(res, indent=1, ensure_ascii=False))


if __name__ == "__main__":
    main()

