def recent(times, now, window):
    return sum(1 for t in times if now - t < window)


def derive(health):
    """Turn raw health into the signals the policy uses."""
    wifi = health.get("wifi", {}) or {}
    route = health.get("route", {}) or {}
    base = health.get("base", {}) or {}
    remote = health.get("remote", {}) or {}
    services = remote.get("services", {}) or {}
    app = remote.get("app", {}) or {}
    svc_ok = bool(services.get("todeskd", True)) and bool(services.get("sunlogin", True))
    cloud_ok = bool(remote.get("cloud_ok"))
    oray_ok = bool(remote.get("oray_ok", cloud_ok))
    todesk_cloud_ok = bool(remote.get("todesk_ok", cloud_ok))
    app_online = app.get("sunlogin_online")
    todesk_ok = app.get("todesk_auth_ok")
    sessions = int(remote.get("sessions", 0) or 0)
    # ESTABLISHED alone is NOT health evidence; only fresh app-level state is.
    app_healthy = (app_online is True) or (todesk_ok is True)
    app_unknown = (app_online is None) and (todesk_ok is None)
    both_clouds_down = (not oray_ok) and (not todesk_cloud_ok)
    remote_healthy = svc_ok and (app_healthy or (cloud_ok and app_unknown))
    remote_healthy = remote_healthy and not (both_clouds_down and not app_healthy)
    return {
        "ssid": wifi.get("ssid", ""), "associated": bool(wifi.get("associated")),
        "connection": wifi.get("connection", ""), "nm_state": wifi.get("nm_state", ""),
        "route_dev": route.get("dev", ""), "hijack": bool(route.get("hijack")),
        "base_ok": bool(base.get("ok")), "cloud_ok": cloud_ok,
        "svc_ok": svc_ok, "app_online": app_online, "sessions": sessions,
        "oray_ok": oray_ok, "todesk_cloud_ok": todesk_cloud_ok,
        "both_clouds_down": both_clouds_down,
        "remote_healthy": remote_healthy, "dl_ok": health.get("download", {}).get("range_ok"),
        "app_healthy": app_healthy,
    }


