    def _limits_ok(self, now):
        if now < self.st.get("cooldown_until", 0):
            return False, "COOLDOWN"
        if now < self.st.get("protect_until", 0):
            return False, "PROTECTED_WINDOW"
        if now - self.st.get("last_switch_ts", 0) < MIN_INTERVAL:
            return False, "COOLDOWN"
        if recent(self.st.get("switch_times", []), now, 3600) >= MAX_HOUR:
            return False, "RATE_LIMIT_HOURLY"
        if recent(self.st.get("switch_times", []), now, 86400) >= MAX_DAY:
            return False, "RATE_LIMIT_DAILY"
