#!/usr/bin/env python3
"""Remote-control service guard (independent of the Wi-Fi watchdog).

Detects the real services on this host, keeps healthy ones untouched, starts a
service that is explicitly stopped, and performs at most one *controlled*
restart for a service that is active but has been unable to authenticate for
several minutes while the network itself is healthy.

Safety:
  * never restarts a service whose app-level evidence is fresh/online;
  * never touches both vendors in one run;
  * no action while the network is in fault or within 180 s of a Wi-Fi switch;
  * per-service cooldown (10 min) and cap (2 restarts/hour), then long backoff;
  * every action and failure is logged; failures never loop tightly.

CLI: remote_guard.py [--apply] [--health ...] [--state ...]
Default is dry-run (prints decisions, performs nothing).
"""
import argparse
import json
import os
import subprocess
import sys
import time

SERVICES = [
    {"key": "sunlogin", "unit": "runsunloginclient.service", "vendor": "SunLogin"},
    {"key": "todesk", "unit": "todeskd.service", "vendor": "ToDesk"},
]
STUCK_CHECKS = 5
STUCK_SECONDS = 300
SETTLE_AFTER_SWITCH = 180
ACTION_COOLDOWN = 600
RESTART_COOLDOWN = 900
MAX_RESTARTS_HOUR = 2
LOG = "/home/bn/net_watchdog/staging/diag/remote_guard.log"


def run(cmd, timeout=20):
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        return p.returncode, (p.stdout + p.stderr).strip()
    except Exception as e:
        return 1, str(e)


def log(event):
    event["ts"] = time.strftime("%Y-%m-%d %H:%M:%S%z")
    try:
        if os.path.exists(LOG) and os.path.getsize(LOG) > 10 * 1024 * 1024:
            os.replace(LOG, LOG + ".1")
        with open(LOG, "a") as f:
            f.write(json.dumps(event, ensure_ascii=False) + "\n")
    except Exception:
        pass


class Exec:
    def active(self, unit):
        rc, out = run(["systemctl", "is-active", unit])
        return out.strip() == "active", out.strip()

    def start(self, unit):
        return run(["systemctl", "start", unit], timeout=60)

    def restart(self, unit):
        return run(["systemctl", "restart", unit], timeout=60)


class FakeExec:
    def __init__(self, states, start_ok=True, restart_ok=True):
        self.states = states          # unit -> active bool
        self.start_ok = start_ok
        self.restart_ok = restart_ok
        self.calls = []

    def active(self, unit):
        return self.states.get(unit, True), "active" if self.states.get(unit, True) else "inactive"

    def start(self, unit):
        self.calls.append(("start", unit))
        if self.start_ok:
            self.states[unit] = True
        return (0, "") if self.start_ok else (1, "permission denied")

    def restart(self, unit):
        self.calls.append(("restart", unit))
        return (0, "") if self.restart_ok else (1, "failed")


def load_json(p, default):
    try:
        return json.load(open(p))
    except Exception:
        return default


def app_online(health, key):
    app = health.get("remote", {}).get("app", {}) or {}
    if key == "sunlogin":
        return app.get("sunlogin_online") is True
    return app.get("todesk_auth_ok") is True


def network_ok(health):
    base = health.get("base", {}) or {}
    remote = health.get("remote", {}) or {}
    route = health.get("route", {}) or {}
    return bool(base.get("ok")) and not route.get("hijack") and bool(remote.get("cloud_ok"))


def decide(health, state, rstate, now, ex, apply_changes):
    """One pass. Returns list of actions (at most one)."""
    acts = []
    last_switch = int(state.get("last_switch_ts", 0) or 0)
    if last_switch and now - last_switch < SETTLE_AFTER_SWITCH:
        return [], "SETTLE_AFTER_SWITCH"
    net_ok = network_ok(health)
    if not net_ok:
        return [], "NETWORK_NOT_HEALTHY"

    candidates = []
    for svc in SERVICES:
        unit = svc["unit"]
        active, raw = ex.active(unit)
        online = app_online(health, svc["key"])
        rs = rstate.setdefault(svc["key"], {
            "stuck": 0, "first_stuck": 0, "last_action": 0,
            "restarts": [], "starts": [], "fails": 0,
        })
        if not active:
            if now - rs.get("last_action", 0) < ACTION_COOLDOWN:
                continue
            if len([t for t in rs.get("starts", []) if now - t < 3600]) >= 3:
                continue
            candidates.append(("start", svc, rs))
            continue
        if online:
            rs["stuck"] = 0
            rs["first_stuck"] = 0
            continue
        # active but offline: wait for the vendor to re-authenticate first
        if rs["stuck"] == 0:
            rs["first_stuck"] = now
        rs["stuck"] += 1
        if (rs["stuck"] >= STUCK_CHECKS and
                now - rs["first_stuck"] >= STUCK_SECONDS and
                now - rs.get("last_action", 0) >= RESTART_COOLDOWN and
                len([t for t in rs.get("restarts", []) if now - t < 3600]) < MAX_RESTARTS_HOUR):
            candidates.append(("restart", svc, rs))

    if not candidates:
        return [], "NOTHING_TO_DO"
    # one service per run; prefer a stopped service over a stuck one
    candidates.sort(key=lambda c: 0 if c[0] == "start" else 1)
    kind, svc, rs = candidates[0]
    if not apply_changes:
        acts.append({"action": kind, "unit": svc["unit"], "vendor": svc["vendor"],
                     "dry_run": True})
        return acts, "DRY_RUN"
    rc, out = (ex.start if kind == "start" else ex.restart)(svc["unit"])
    rs["last_action"] = now
    if kind == "start":
        rs.setdefault("starts", []).append(now)
    else:
        rs.setdefault("restarts", []).append(now)
    if rc == 0:
        rs["fails"] = 0
        acts.append({"action": kind, "unit": svc["unit"], "vendor": svc["vendor"],
                     "ok": True})
