# 3) NM roamed by itself: observe, never fight it
if st.get("last_connection") and cur and cur != st["last_connection"]:
    st["obs_until"] = now + OBSERVE
    st["cooldown_until"] = max(st.get("cooldown_until", 0), now + OBSERVE)
    self._record(now, "NM_ROAM", frm=st["last_connection"], to=cur)
if cur:
    st["last_connection"] = cur

# 4) route hijack is never a Wi-Fi problem
if d["hijack"]:
    self._set(now, "DEGRADED", "ROUTE_HIJACK(%s)" % d["route_dev"])
    return self._result("none", "ROUTE_HIJACK")

# 5) services down: not blamed on Wi-Fi
if d["remote_reason"] == "REMOTE_SERVICE_FAILURE":
    self._set(now, "DEGRADED", "REMOTE_SERVICE_DEGRADED")
    return self._result("none", "REMOTE_SERVICE_DEGRADED")

# V3.3: no fixed protection window; recovery is never time-blocked.

# 6) healthy or one-vendor-only: never switch
if d["remote_reason"] in ("REMOTE_HEALTHY", "REMOTE_PARTIAL"):
    st["persist_until"] = 0
    st["consecutive_failures"] = 0
    st["first_failure_ts"] = 0
    if now - st.get("last_switch_ts", 0) > STABLE_RESET:
        st["failures_since_success"] = 0
    if st["state"] == "PROTECTED" and now >= st.get("protect_until", 0):
        st["protect_until"] = 0
    if d["remote_reason"] == "REMOTE_PARTIAL":
        self._set(now, "DEGRADED", "REMOTE_PARTIAL")
        return self._result("none", "REMOTE_PARTIAL")
    if d["dl_ok"] is False:
        self._set(now, "DEGRADED", "DOWNLOAD_DEGRADED")
    else:
        self._set(now, "HEALTHY", "")
    return self._result("none", st["status"] or "HEALTHY")

# 7) auth failure with working network: never switch
if d["remote_reason"] == "REMOTE_AUTH_FAILURE":
    self._set(now, "DEGRADED", "REMOTE_AUTH_FAILURE")
    return self._result("none", "REMOTE_AUTH_FAILURE")

# 8) unknown with a healthy path: keep diagnosing
link_broken = (not d["link_ok"]) or (not d["base_ok"])
if d["remote_reason"] == "REMOTE_UNKNOWN" and not link_broken:
    self._set(now, "DEGRADED", "REMOTE_UNKNOWN")
    return self._result("none", "REMOTE_UNKNOWN")

# 9) a live interactive session protects the current link
if d["active_session"] and d["remote_reason"] != "REMOTE_CONNECTIVITY_FAILURE":
    self._set(now, "DEGRADED", "ACTIVE_SESSION_PROTECT")
    return self._result("none", "ACTIVE_SESSION_PROTECT")

# 10) failure tracking (link broken, or both clouds down)
if st["consecutive_failures"] == 0:
    st["first_failure_ts"] = now
st["consecutive_failures"] += 1
sustained = (st["consecutive_failures"] >= FAIL_CHECKS and
             now - st["first_failure_ts"] >= FAIL_SECONDS)
fault = "NETWORK_UNREACHABLE" if link_broken else "REMOTE_CONNECTIVITY_FAILURE"
if not sustained:
    self._set(now, "DEGRADED", fault)
    return self._result("none", fault)
# V3.3: no fixed protection window blocks recovery.
self._set(now, "FAILURE_CONFIRMED", fault)
ok, why = self._limits_ok(now)
if not ok:
    if now - st.get("first_failure_ts", now) >= PERSIST_ENTER:
        return self._enter_persistent(now, why)
    self._set(now, "COOLDOWN", why)
    return self._result("none", why)

target = self._target(health)
tok, twhy = self._target_ok(target, now)
if not tok:
    self._set(now, "FAILURE_CONFIRMED", twhy)
    return self._result("none", twhy)

if self.shadow:
    self._record(now, "SHADOW_RECOMMEND", target=target, fault=fault)

