    for key in S:
        sims = S[key][1][:7]
        gaps = [sims[i] - sims[i + 1] for i in range(6)]
        i = max(range(6), key=lambda j: gaps[j]) + 1
        ks.append(1 if i <= 1 else 3 if i <= 3 else 5 if i <= 5 else 7)
    return sum(ks) / len(ks), {k: ks.count(k) for k in (1, 3, 5, 7)}


