#!/usr/bin/env python3
"""Fixed-DF Oracle1/3/7 and Good/Hard/Easy analysis."""
import json
import os
import random
import sys

ROOT = "/home/bn/videoufo_research"
OUT = os.path.join(ROOT, "evcap_external/outputs")
NAME = "eval_evcap_top7_bs1_load_video_feature_sim_score_cross_fusion_gate_not_share_linear_prompt5_review_generated_captions.json"
sys.path.insert(0, os.path.join(ROOT, "evcap_external/evaluation"))
from pycocoevalcap.cider.cider import Cider  # noqa: E402

variants = ["D1", "D3", "D7", "oracle1", "oracle3", "oracle7",
            "goodtail7", "hardwrong7", "easywrong7"]
P, M = {}, {}
for v in variants:
    d = os.path.join(OUT, f"eval_val497_{v}")
    fp = os.path.join(d, NAME)
    if os.path.exists(fp):
        P[v] = {x["image_name"]: x["prediction"].strip() for x in json.load(open(fp))}
        M[v] = json.load(open(os.path.join(d, "metrics.json")))
Q = sorted(set.intersection(*[set(p) for p in P.values()]))
rows = json.load(open(os.path.join(OUT, "eval_val497_D3", NAME)))
GT = {x["image_name"]: x["captions"] for x in rows}
g = {q: GT[q] for q in Q}
C = {v: dict(zip(Q, Cider().compute_score(g, {q: [P[v][q]] for q in Q})[1])) for v in P}
rng = random.Random(42)


def pair(a, b):
    d = [C[a][q] - C[b][q] for q in Q]
    obs = sum(d) / len(d)
    boots = sorted(sum(d[rng.randrange(len(d))] for _ in range(len(d))) / len(d) for _ in range(10000))
    cnt = sum(1 for _ in range(10000)
              if abs(sum(x if rng.random() < 0.5 else -x for x in d) / len(d)) >= abs(obs))
    return {"diff": round(obs * 100, 2), "ci95": [round(boots[250] * 100, 2), round(boots[9750] * 100, 2)],
            "p": round((cnt + 1) / 10001, 5)}


out = {"n": len(Q), "cider": {v: round(M[v]["CIDEr"] * 100, 2) for v in P}, "pairs": {}}
for a, b in [("oracle1", "D1"), ("oracle3", "D3"), ("oracle7", "D7"),
             ("goodtail7", "D7"), ("hardwrong7", "D7"), ("easywrong7", "D7"),
             ("hardwrong7", "easywrong7"), ("oracle7", "oracle3"), ("oracle3", "oracle1")]:
    if a in P and b in P:
        out["pairs"][f"{a}-{b}"] = pair(a, b)
json.dump(out, open(os.path.join(ROOT, "reports/oracle_distractor_stats.json"), "w"), indent=2)
print(json.dumps(out, indent=2))

